from httpbin.core import app
client = app.test_client()

def test_delete_plain_returns_200_with_required_keys():
    r = client.delete('/delete')
    assert r.status_code == 200
    body = r.get_json()
    assert body is not None
    required_keys = {'url', 'args', 'headers', 'form', 'data', 'files', 'json', 'origin'}
    assert set(body.keys()) >= required_keys
    assert body['args'] == {}
    assert body['form'] == {}
    assert body['json'] is None
    assert body['data'] == ''
    assert body['files'] == {}
    assert 'url' in body and '/delete' in body['url']

test_delete_plain_returns_200_with_required_keys()

from httpbin.core import app
client = app.test_client()

def test_delete_empty_body_boundary():
    r = client.delete('/delete', data=b'')
    assert r.status_code == 200
    body = r.get_json()
    assert body is not None
    assert body['data'] == ''
    assert body['json'] is None
    assert body['form'] == {}
    assert body['files'] == {}
    assert body['args'] == {}

test_delete_empty_body_boundary()
